function proxyTo(request, response, hostname, port, path) {
  const proxy = http.request({ hostname, port, method: request.method, path, headers: { ...request.headers, host: hostname } }, upstreamResponse => {
    response.writeHead(upstreamResponse.statusCode ?? 502, upstreamResponse.headers);
    upstreamResponse.pipe(response);
  });
  proxy.setTimeout(30_000, () => proxy.destroy(new Error("upstream timeout")));
  proxy.on("error", error => {
    if (!response.headersSent) response.writeHead(502, { "content-type": "application/json; charset=utf-8" });
    response.end(JSON.stringify({ status: "UPSTREAM_ERROR", message: error.message }));
  });
  request.pipe(proxy);
}

function p006SessionToken(request){
  const matches=(request.headers.cookie||"").split(";").map(value=>value.trim()).filter(value=>value.startsWith("P006_SESSION="));
  const token=matches.length===1?matches[0].slice(13):"";
  return /^[A-Za-z0-9_-]{32,128}$/.test(token)?token:"";
}

function trustedP006MutationOrigin(request){
  const origin=request.headers.origin;
  return !origin||P006_MUTATION_ORIGINS.has(origin);
}

function sendP006Json(response,status,payload){
  response.writeHead(status,{"content-type":"application/json; charset=utf-8","cache-control":"no-store"});
  response.end(JSON.stringify(payload));
}

function authorizeP006(request,response,roles,permissions,onAuthorized){
  const token=p006SessionToken(request);
  if(!token)return sendP006Json(response,401,{status:"AUTH_REQUIRED",authenticated:false});
  const child=spawn("python3",[P006_SCENARIO_STORE,"authz",roles.join(","),permissions.join(",")],{env:{...process.env,P006_SESSION_TOKEN:token}});
  let output="",error="",settled=false,timedOut=false;
  const timeout=setTimeout(()=>{timedOut=true;child.kill("SIGKILL")},8000);timeout.unref();
  child.stdout.on("data",data=>output+=data);
  child.stderr.on("data",data=>error+=data);
  child.on("error",failure=>{if(settled)return;settled=true;clearTimeout(timeout);sendP006Json(response,503,{status:"AUTHZ_UNAVAILABLE",message:failure.message})});
  child.on("close",code=>{
    if(settled)return;settled=true;clearTimeout(timeout);
    let payload={};try{payload=JSON.parse(output.trim()||"{}")}catch{}
    if(code===0&&payload.authenticated===true)return onAuthorized(payload.actor,payload);
    if(code===4)return sendP006Json(response,401,{status:"AUTH_REQUIRED",authenticated:false});
    if(code===3)return sendP006Json(response,403,{status:"FORBIDDEN",authenticated:true,message:payload.message||"요청한 업무 권한이 없습니다."});
    sendP006Json(response,503,{status:"AUTHZ_UNAVAILABLE",message:(timedOut?"authorization timed out":error||payload.message||"authorization failed").slice(-500)});
  });
}

function p006AuthzApi(request,response){
  if(request.method!=="GET"){response.writeHead(405,{"allow":"GET"});return response.end()}
  authorizeP006(request,response,[],[],(_actor,payload)=>sendP006Json(response,200,payload));
}

function syncUsd(request, response) {
  if (request.method !== "POST") { response.writeHead(405); return response.end(); }
  if(!String(request.headers["content-type"]||"").toLowerCase().startsWith("application/json"))return sendP006Json(response,415,{status:"UNSUPPORTED_MEDIA_TYPE"});
  if(!trustedP006MutationOrigin(request))return sendP006Json(response,403,{status:"FORBIDDEN_ORIGIN"});
  const chunks=[];let size=0,oversized=false;
  request.on("data",chunk=>{size+=chunk.length;if(size<=2_000_000)chunks.push(chunk);else oversized=true});
  request.on("end",()=>{
    if(oversized)return sendP006Json(response,413,{status:"PAYLOAD_TOO_LARGE"});
    const body=Buffer.concat(chunks);let payload={};try{payload=JSON.parse(body.toString()||"{}")}catch{}
    const scenarioSync=payload.scenario&&typeof payload.scenario==="object";
    const roles=scenarioSync?P006_SCENARIO_ROLES:P006_USD_SYNC_SCENE_ROLES;
    const permissions=scenarioSync?P006_SCENARIO_PERMISSIONS:P006_USD_SYNC_SCENE_PERMISSIONS;
    authorizeP006(request,response,roles,permissions,(actor)=>{
      const child=spawn("python3",["/home/sjkim/OmniverseProjects/sync_p006_layout_to_usd.py"],{env:{...process.env,P006_SCENE_STDIN:"1",P006_ACTOR_ID:String(actor.accountId||"")}});
      let output="",error="";child.stdout.on("data",d=>output+=d);child.stderr.on("data",d=>error+=d);
      child.on("close",code=>{response.writeHead(code===0?200:500,{"content-type":"application/json; charset=utf-8","cache-control":"no-store"});response.end(code===0?(output.trim()||'{"status":"SYNCED"}'):JSON.stringify({status:"SYNC_FAILED",message:error.slice(-1000)}));});
      child.stdin.end(body);
    });
  });
}

